.box {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 5px solid;
}

/* before */
.card { box-sizing: content-box; }
/* after */
*,
*::before,
*::after {
  box-sizing: border-box;
}

/* bug */
input {
  width: 100%;
  padding: 12px;
}
/* fix */
input {
  box-sizing: border-box;
}

.card {
  position: relative;
}
.card .tag {
  position: absolute;
  top: 8px;
  right: 8px;
}

/* bug: badge jumps to page corner */
.badge { position: absolute; top: 0; right: 0; }
/* fix */
.card { position: relative; }

header {
  position: sticky;
  top: 0;
  background: white;
}

/* this ancestor breaks sticky */
.wrapper {
  overflow: hidden;
}
/* fix: remove it, or use overflow: clip */
.wrapper {
  overflow: clip;
}

.a {
  position: relative;
  z-index: 1;
}
.a .popup { z-index: 9999; }
.b {
  position: relative;
  z-index: 2;
}

html { font-size: 100%; }
h1 { font-size: 2rem; }
.btn {
  font-size: 1rem;
  padding: 0.5em 1em;
}

/* with the default root size */
/* 1rem = 16px */
/* 2rem = 32px */
.title { font-size: 2rem; }
